package com.oms.channel.platform;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import java.util.*;
import static com.oms.channel.platform.ChannelPlatformService.map;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class RefundPlatformServiceTest {
 ChannelPlatformTest f=new ChannelPlatformTest();RefundPlatformService refunds;TmallClient client;
 @BeforeEach void setup(){f.setup();f.db.update("DELETE FROM channel_refund_access");f.db.update("DELETE FROM channel_refund_command");f.db.update("DELETE FROM channel_refund_sim");refunds=new RefundPlatformService();refunds.db=f.db;refunds.platform=f.service;refunds.secrets=f.secrets;client=mock(TmallClient.class);refunds.client=client;PlatformInteractionLog logs=new PlatformInteractionLog();logs.db=f.db;logs.transactionManager=new DataSourceTransactionManager(f.db.getDataSource());refunds.logs=logs;}
 @AfterEach void close(){f.closePool();}
 void access(boolean pay){refunds.access("QM",101,map("revision",0,"read_enabled",1,"write_enabled",1,"payment_enabled",pay?1:0,"ignore_code",0),"test");}
 @Test void capabilityModeComesFromShopBindingAndRequiresNoVendorRequest(){assertEquals("REAL",refunds.capability("QM",101).get("execution_mode"));f.simulation(true);f.service.simulate("QM",101,"test");assertEquals("SIMULATION",refunds.capability("QM",101).get("execution_mode"));verifyNoInteractions(client);}
 @Test void simulationCanLosePaymentResponseAfterActualVendorSuccessWithoutRepeatingPayment(){
  f.simulation(true);f.service.simulate("QM",101,"test");access(true);
  f.db.update("UPDATE channel_refund_access a JOIN channel_platform_binding b ON b.company_code=a.company_code AND b.channel_id=a.channel_id SET a.payment_session_cipher=b.token_cipher,a.payment_expires_at=b.token_expires_at,a.payment_app_id=b.app_id,a.payment_seller_id=b.seller_id,a.payment_sub_id='SIM_SUB' WHERE a.company_code='QM' AND a.channel_id=101");
  f.db.update("INSERT INTO channel_refund_sim(company_code,channel_id,refund_id,modified,payload) VALUES ('QM',101,'9007199254740993','2026-10-01 00:00:00',?)",RefundPlatformService.json(map("refund",map("refund_id","9007199254740993","refund_version","2","status","WAIT_SELLER_CONFIRM_GOODS","modified","2026-10-01 00:00:00","_local_test_pay_response_loss",true))));
  Map<String,Object> pay=map("operation","PAY","refund_id","9007199254740993","request_id","SIM_PAY_RESPONSE_LOST","args",map("refund_infos","9007199254740993|2500|2|aftersale","ignore_code",false,"code","123456"));
  assertEquals("UNKNOWN",refunds.call("QM",101,pay).get("outcome"));assertEquals("SUCCESS",RefundPlatformService.read(f.db.queryForObject("SELECT payload FROM channel_refund_sim",String.class)).path("refund_get_response").path("refund").path("status").asText());
  assertEquals("UNKNOWN",refunds.call("QM",101,pay).get("outcome"));assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM channel_refund_command",Integer.class));verifyNoInteractions(client);
 }
 Map<String,Object> command(String id){return map("operation","REVIEW","refund_id","9007199254740993","request_id",id,"args",map("refund_id","9007199254740993","refund_version","2","result",true),"actor","test");}
 @Test void authorizationAndReadFlagsAreRequiredBeforeAnyVendorCall(){assertThrows(IllegalArgumentException.class,()->refunds.call("QM",101,command("REFUND_CMD_1")));f.authorize();assertThrows(IllegalArgumentException.class,()->refunds.call("QM",101,command("REFUND_CMD_1")));verifyNoInteractions(client);}
 @Test void knownWriteResultIsReusedAndChangedRequestContentIsRejected()throws Exception{f.authorize();access(false);when(client.api(anyString(),anyString(),anyString(),anyString(),anyMap())).thenReturn(new ObjectMapper().readTree("{\"rp_refund_review_response\":{\"is_success\":true}}"));Map<String,Object> command=command("REFUND_CMD_2");assertEquals("RECEIVED",refunds.call("QM",101,command).get("outcome"));assertEquals("RECEIVED",refunds.call("QM",101,command).get("outcome"));((Map<String,Object>)command.get("args")).put("refund_version","3");assertThrows(IllegalArgumentException.class,()->refunds.call("QM",101,command));verify(client,times(1)).api(anyString(),anyString(),anyString(),anyString(),anyMap());}
 @Test void unknownTransportResultNeverResendsOriginalWrite(){f.authorize();access(false);when(client.api(anyString(),anyString(),anyString(),anyString(),anyMap())).thenThrow(new TmallClient.Failure("isp.timeout",true));assertEquals("UNKNOWN",refunds.call("QM",101,command("REFUND_CMD_3")).get("outcome"));assertEquals("UNKNOWN",refunds.call("QM",101,command("REFUND_CMD_3")).get("outcome"));verify(client,times(1)).api(anyString(),anyString(),anyString(),anyString(),anyMap());assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM channel_refund_command",Integer.class));}
 @Test void paymentTokenCannotBeUsedAcrossAppOrSeller(){f.authorize();access(true);f.db.update("UPDATE channel_refund_access SET payment_session_cipher=?,payment_expires_at=DATE_ADD(NOW(),INTERVAL 1 DAY),payment_app_id=?,payment_seller_id='OTHER_SELLER'",f.secrets.encrypt("CHILD_TOKEN"),f.app);Map<String,Object> body=map("operation","PAY","refund_id","9007199254740993","request_id","REFUND_PAY_1","args",map("refund_infos","9007199254740993|2500|2|onsale","ignore_code",false,"code","123456"));assertThrows(IllegalArgumentException.class,()->refunds.call("QM",101,body));verifyNoInteractions(client);}
 @Test void invalidProofIsRejectedBeforeCreatingWriteIntent(){f.authorize();access(false);Map<String,Object> body=command("REFUND_IMG_1");((Map<String,Object>)body.get("args")).put("proof_base64",Base64.getEncoder().encodeToString(new byte[]{1,2,3}));assertThrows(IllegalArgumentException.class,()->refunds.call("QM",101,body));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM channel_refund_command",Integer.class));verifyNoInteractions(client);}
 @Test void localCancellationRateKeysDoNotRequirePlatformBinding(){assertTrue(refunds.rateKeys("QM",103).isEmpty());assertThrows(IllegalArgumentException.class,()->refunds.rateKeys("OTHER",101));}
 @Test void refundSubaccountGrantDoesNotOverwriteMainAndIsClearedOnDisable()throws Exception{f.authorize();String main=f.db.queryForObject("SELECT token_cipher FROM channel_platform_binding",String.class);ReflectionTestUtils.setField(f.service,"client",client);when(client.token(anyMap())).thenReturn(new ObjectMapper().readTree("{\"access_token\":\"CHILD_PRIVATE\",\"expires_in\":86400,\"taobao_user_id\":\"SELLER-1\",\"sub_taobao_user_id\":\"12345678\"}"));String url=f.service.authorizeRefundPayment("QM",101,7,"test"),state=url.substring(url.lastIndexOf("&state=")+7);f.service.complete("QM",7,state,"CHILD_CODE","test");assertEquals(main,f.db.queryForObject("SELECT token_cipher FROM channel_platform_binding",String.class));assertTrue(Boolean.TRUE.equals(refunds.capability("QM",101).get("payment_authorized")));f.service.disable("QM",101,"test");assertNull(f.db.queryForObject("SELECT payment_session_cipher FROM channel_refund_access",String.class));assertEquals(main.length()>0,true);}
 @Test void ordinarySimulationListHonorsFixedWindowAndPagination(){f.simulation(true);f.service.simulate("QM",101,"test");access(false);for(int i=1;i<=3;i++)f.db.update("INSERT INTO channel_refund_sim(company_code,channel_id,refund_id,modified,payload) VALUES ('QM',101,?,'2026-10-01 00:01:00',?)",String.valueOf(i),RefundPlatformService.json(map("refund",map("refund_id",String.valueOf(i)))));Map<String,Object> body=map("operation","LIST","refund_id","","args",map("start_modified","2026-10-01 00:00:00","end_modified","2026-10-01 00:02:00","page_no",2,"page_size",2));Map<String,Object> data=(Map<String,Object>)refunds.call("QM",101,body).get("data");assertEquals(false,data.get("has_next"));assertEquals(1,((List<?>)((Map<?,?>)data.get("refunds")).get("refund")).size());verifyNoInteractions(client);}
 @Test void batchCapabilitiesMatchSingleShopAndNeverCallVendorOrExposeCredentials(){f.authorize();access(false);ChannelPlatformService batch=spy(f.service);refunds.platform=batch;List<Map<String,Object>> rows=refunds.capabilities("QM");Map<String,Object> first=rows.stream().filter(row->"101".equals(String.valueOf(row.get("channel_id")))).findFirst().get();assertEquals(true,first.get("available"));assertEquals(true,first.get("can_query"));assertEquals(1,((Number)first.get("write_enabled")).intValue());verify(batch,never()).detail(anyString(),anyLong());String encoded=RefundPlatformService.json(rows);assertFalse(encoded.contains("cipher"));assertFalse(encoded.contains("app_key"));assertFalse(encoded.contains("access_token"));assertTrue(refunds.capabilities("OTHER").stream().noneMatch(row->"101".equals(String.valueOf(row.get("channel_id")))));verifyNoInteractions(client);}

 @Test void simulationPaymentAdvancesVersionAndOriginalWriteIsReused(){f.simulation(true);f.service.simulate("QM",101,"test");access(true);f.db.update("UPDATE channel_refund_access SET payment_session_cipher=?,payment_expires_at=DATE_ADD(NOW(),INTERVAL 1 DAY),payment_app_id=?,payment_sub_id='SIM_SUB',payment_seller_id='SIM-101'",f.secrets.encrypt("SIM_CHILD"),f.db.queryForObject("SELECT app_id FROM channel_platform_binding WHERE channel_id=101",Long.class));String seller=f.db.queryForObject("SELECT seller_id FROM channel_platform_binding WHERE channel_id=101",String.class);f.db.update("UPDATE channel_refund_access SET payment_seller_id=?",seller);f.db.update("INSERT INTO channel_refund_sim(company_code,channel_id,refund_id,modified,payload) VALUES ('QM',101,'9007199254740993','2026-10-01 00:00:00',?)",RefundPlatformService.json(map("refund",map("refund_id","9007199254740993","refund_version","2","status","WAIT_SELLER_AGREE","modified","2026-10-01 00:00:00"))));Map<String,Object> body=map("operation","PAY","refund_id","9007199254740993","request_id","SIM_PAY_VERSION","args",map("refund_infos","9007199254740993|2500|2|aftersale","ignore_code",false,"code","123456"));assertEquals("RECEIVED",refunds.call("QM",101,body).get("outcome"));assertEquals("RECEIVED",refunds.call("QM",101,body).get("outcome"));com.fasterxml.jackson.databind.JsonNode current=RefundPlatformService.read(f.db.queryForObject("SELECT payload FROM channel_refund_sim",String.class)).path("refund_get_response").path("refund");assertEquals("SUCCESS",current.path("status").asText());assertEquals("3",current.path("refund_version").asText());assertTrue(current.path("modified").asText().compareTo("2026-10-01 00:00:00")>0);assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM channel_refund_command",Integer.class));verifyNoInteractions(client);}
 @Test void simulationCancellationFeedbackHasExplicitBusinessSuccess(){f.simulation(true);f.service.simulate("QM",101,"test");access(false);Map<String,Object> result=refunds.call("QM",101,map("operation","CANCEL_FEEDBACK","refund_id","9007199254740993","request_id","SIM_CANCEL_FEEDBACK","args",map("refund_id","9007199254740993","seller_id","SIM-101","result",true)));assertEquals("RECEIVED",result.get("outcome"));assertTrue(RefundPlatformService.read(RefundPlatformService.json(result.get("data"))).path("result").path("result_data").path("success").asBoolean());verifyNoInteractions(client);}
}
